(() => {
  'use strict';
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const W = 960, H = 540, floor = 443;
  const $ = (id) => document.getElementById(id);
  const intro = $('intro'), result = $('result');
  let running = false, ended = false, last = 0, time = 0, shake = 0, soundOn = true, audio;
  let keys = Object.create(null), pressed = Object.create(null), particles = [], projectiles = [], waves = [], hitStop = 0;
  const player = {x:270,y:floor,vx:0,vy:0,face:1,hp:5,maxHp:5,onGround:true,attack:0,attackCd:0,dash:0,dashCd:0,invuln:0,stun:0,soul:0,anim:0};
  const boss = {x:700,y:floor,vx:0,vy:0,face:-1,hp:12,maxHp:12,state:'idle',timer:1.4,attackCd:0,invuln:0,flash:0,phase:1,anim:0};
  const rnd = (a,b) => a + Math.random()*(b-a);
  const clamp = (v,a,b) => Math.max(a,Math.min(b,v));
  function resize(){const dpr=Math.min(devicePixelRatio||1,2),r=canvas.getBoundingClientRect();canvas.width=Math.round(r.width*dpr);canvas.height=Math.round(r.height*dpr);ctx.setTransform(canvas.width/W,0,0,canvas.height/H,0,0)}
  new ResizeObserver(resize).observe(canvas); resize();
  function sound(freq=220,dur=.08,type='sine',vol=.035){if(!soundOn)return;try{audio ||= new (window.AudioContext||window.webkitAudioContext)();const o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.setValueAtTime(freq,audio.currentTime);o.frequency.exponentialRampToValueAtTime(Math.max(45,freq*.55),audio.currentTime+dur);g.gain.setValueAtTime(vol,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+dur);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+dur)}catch(_){}}
  function reset(){Object.assign(player,{x:270,y:floor,vx:0,vy:0,face:1,hp:5,attack:0,attackCd:0,dash:0,dashCd:0,invuln:0,stun:0,soul:0,onGround:true,anim:0});Object.assign(boss,{x:700,y:floor,vx:0,vy:0,face:-1,hp:12,state:'idle',timer:1.3,attackCd:0,invuln:0,flash:0,phase:1,anim:0});particles=[];projectiles=[];waves=[];shake=0;ended=false;running=true;updateHud();intro.classList.add('hidden');result.classList.add('hidden');$('fightHint').style.opacity=1}
  function start(){if(audio&&audio.state==='suspended')audio.resume();if(!running)reset()}
  $('startButton').addEventListener('click',start);$('restartButton').addEventListener('click',()=>{reset();if(audio&&audio.state==='suspended')audio.resume()});
  $('soundButton').addEventListener('click',()=>{soundOn=!soundOn;$('soundIcon').textContent=soundOn?'♫':'♪';if(soundOn)sound(420,.09,'triangle')});
  const controls={left:['ArrowLeft','a','A'],right:['ArrowRight','d','D'],jump:[' ','ArrowUp','w','W'],attack:['j','J','z','Z'],dash:['k','K','Shift'],heal:['h','H']};
  addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','ArrowUp',' ','Shift'].includes(e.key))e.preventDefault();if(!keys[e.key])pressed[e.key]=true;keys[e.key]=true;if((e.key==='Enter'||e.key===' ')&&!running&&!ended&&intro.classList.contains('hidden'))start();if(ended&&(e.key==='Enter'||e.key===' '))reset()},{passive:false});
  addEventListener('keyup',e=>{keys[e.key]=false});
  document.querySelectorAll('[data-control]').forEach(btn=>{const name=btn.dataset.control,code={left:'ArrowLeft',right:'ArrowRight',jump:' ',dash:'k',attack:'j'}[name];const down=e=>{e.preventDefault();keys[code]=true;pressed[code]=true};const up=e=>{e.preventDefault();keys[code]=false};btn.addEventListener('pointerdown',down);btn.addEventListener('pointerup',up);btn.addEventListener('pointerleave',up);btn.addEventListener('pointercancel',up)});
  function held(name){return controls[name].some(k=>keys[k])}function tapped(name){return controls[name].some(k=>pressed[k])}
  function updateHud(){const health=$('playerHealth');health.innerHTML='';for(let i=0;i<player.maxHp;i++){const m=document.createElement('i');m.className='mask'+(i>=player.hp?' empty':'');health.appendChild(m)}$('soulCount').textContent=player.soul;$('soulFill').style.width=Math.min(100,player.soul/3*100)+'%';$('bossHealth').style.width=(boss.hp/boss.maxHp*100)+'%';const pips=$('bossPips');pips.innerHTML='';for(let i=1;i<boss.maxHp;i++){const b=document.createElement('b');b.style.position='relative';b.style.width='1px';pips.appendChild(b)}}
  function puff(x,y,color,n=8,speed=110){for(let i=0;i<n;i++){const a=rnd(0,Math.PI*2),v=rnd(speed*.25,speed);particles.push({x,y,vx:Math.cos(a)*v,vy:Math.sin(a)*v,life:rnd(.25,.65),max:.65,size:rnd(1.5,4),color})}}
  function damagePlayer(amount=1,knock=1){if(player.invuln>0||ended)return;player.hp=Math.max(0,player.hp-amount);player.invuln=1.15;player.stun=.22;player.vx=-player.face*220*knock;player.vy=-140;shake=8;puff(player.x,player.y-28,'#b4dce4',12,140);sound(145,.2,'sawtooth',.055);updateHud();if(player.hp<=0)finish(false)}
  function damageBoss(amount=1){if(boss.invuln>0||ended)return;boss.hp=Math.max(0,boss.hp-amount);boss.invuln=.18;boss.flash=.16;boss.vx=player.face*48;shake=4;hitStop=.045;player.soul=Math.min(3,player.soul+1);puff(boss.x,boss.y-48,'#eed7a2',9,115);sound(300,.09,'triangle',.04);updateHud();if(boss.hp<=6)boss.phase=2;if(boss.hp<=0)finish(true)}
  function finish(win){ended=true;running=false;result.classList.remove('hidden');$('resultEyebrow').textContent=win?'THE TOLL IS PAID':'THE DARK TAKES YOU';$('resultTitle').innerHTML=win?'THE CHAPEL<br><em>IS QUIET</em>':'A LIGHT<br><em>GOES OUT</em>';$('resultCopy').textContent=win?'The old bell falls silent. The dark remembers.':'The Warden returns to its vigil. Rise, little vessel.';$('resultOrnament').textContent=win?'✦   ✧   ✦':'✧';$('fightHint').style.opacity=0;sound(win?540:90,.5,win?'sine':'sawtooth',.06)}
  function beginBossAttack(){boss.face=player.x<boss.x?-1:1;const d=Math.abs(player.x-boss.x);if(boss.phase===2&&Math.random()<.48){boss.state='bellWind';boss.timer=.82;sound(165,.28,'sine',.04)}else if(d>290){boss.state='bellWind';boss.timer=.78;sound(165,.28,'sine',.04)}else if(Math.random()<.5){boss.state='dashWind';boss.timer=.65;sound(110,.22,'sawtooth',.04)}else{boss.state='slamWind';boss.timer=.8;sound(90,.3,'sine',.05)}}
  function update(dt){time+=dt;if(!running||ended)return;if(hitStop>0){hitStop-=dt;return}player.anim+=dt;boss.anim+=dt;if(shake>0)shake=Math.max(0,shake-dt*20);
    for(const k in pressed)delete pressed[k];
    let move=(held('right')?1:0)-(held('left')?1:0);
    if(player.stun>0)player.stun-=dt;else if(player.dash<=0){if(move){player.face=move;player.vx=move*(player.onGround?230:195)}else player.vx*=player.onGround?.75:.98}
    if(tapped('jump')&&player.onGround&&player.stun<=0){player.vy=-480;player.onGround=false;sound(210,.08,'sine',.02);puff(player.x,floor,'#94a9b5',4,50)}
    if(tapped('dash')&&player.dashCd<=0&&player.stun<=0){player.dash=.19;player.dashCd=.75;player.invuln=Math.max(player.invuln,.23);player.vx=player.face*610;player.vy=0;sound(360,.12,'triangle',.025);puff(player.x-player.face*14,player.y-20,'#b8d7dc',7,85)}
    if(tapped('attack')&&player.attackCd<=0&&player.stun<=0){player.attack=.19;player.attackCd=.34;sound(260,.07,'triangle',.022)}
    if(tapped('heal')&&player.soul>=3&&player.hp<player.maxHp){player.soul=0;player.hp=Math.min(player.maxHp,player.hp+1);puff(player.x,player.y-25,'#bca9ea',16,70);sound(500,.38,'sine',.04);updateHud()}
    if(player.dash>0)player.dash-=dt;else if(player.stun<=0&&move===0)player.vx*=Math.pow(.001,dt);
    player.attack=Math.max(0,player.attack-dt);player.attackCd=Math.max(0,player.attackCd-dt);player.dashCd=Math.max(0,player.dashCd-dt);player.invuln=Math.max(0,player.invuln-dt);player.vy+=1250*dt;player.x+=player.vx*dt;player.y+=player.vy*dt;
    if(player.y>=floor){player.y=floor;player.vy=0;player.onGround=true}else player.onGround=false;player.x=clamp(player.x,65,895);
    if(player.attack>.1&&Math.abs(player.x-boss.x)<88&&Math.abs((player.y-29)-(boss.y-45))<63&&boss.invuln<=0)damageBoss(1);
    updateBoss(dt);
    for(let i=projectiles.length-1;i>=0;i--){const p=projectiles[i];p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=220*dt;p.life-=dt;if(p.life<=0||p.x<40||p.x>920){puff(p.x,p.y,'#bf9e75',5,50);projectiles.splice(i,1);continue}if(Math.abs(p.x-player.x)<24&&Math.abs(p.y-(player.y-28))<30){damagePlayer();projectiles.splice(i,1)}}
    for(let i=waves.length-1;i>=0;i--){const w=waves[i];w.x+=w.vx*dt;w.life-=dt;if(w.life<=0||w.x<40||w.x>920){waves.splice(i,1);continue}if(Math.abs(w.x-player.x)<24&&player.y>=floor-35)damagePlayer(1,1)}
    for(let i=particles.length-1;i>=0;i--){const p=particles[i];p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=180*dt;p.life-=dt;if(p.life<=0)particles.splice(i,1)}
    if(Math.random()<.022)puff(rnd(90,870),rnd(160,410),'rgba(183,200,208,.65)',1,8);
    if(Math.floor(time)%4===0&&Math.random()<.002)updateHud();
  }
  function updateBoss(dt){boss.invuln=Math.max(0,boss.invuln-dt);boss.flash=Math.max(0,boss.flash-dt);boss.attackCd=Math.max(0,boss.attackCd-dt);const d=Math.abs(player.x-boss.x);if(boss.state==='idle'){boss.face=player.x<boss.x?-1:1;boss.vx+=(boss.face*-0)*dt;boss.timer-=dt;if(d>210)boss.x+=Math.sign(player.x-boss.x)*Math.min(90*dt,d-190);if(boss.timer<=0&&boss.attackCd<=0)beginBossAttack()}
    else if(boss.state==='dashWind'){boss.timer-=dt;boss.x+=Math.sin(time*28)*.6;if(boss.timer<=0){boss.state='dash';boss.timer=.48;boss.vx=boss.face*520;sound(120,.24,'sawtooth',.04)}}
    else if(boss.state==='dash'){boss.timer-=dt;boss.x+=boss.vx*dt;if(Math.abs(boss.x-player.x)<48&&Math.abs(boss.y-player.y)<65)damagePlayer(1,1.35);if(boss.timer<=0||boss.x<80||boss.x>880){boss.state='recover';boss.timer=.62;boss.vx=0;puff(boss.x,floor-8,'#b58a66',10,70)}}
    else if(boss.state==='slamWind'){boss.timer-=dt;boss.x+=Math.sign(player.x-boss.x)*28*dt;if(boss.timer<=0){boss.state='air';boss.timer=.55;boss.vy=-560;boss.vx=boss.face*95;sound(120,.14,'sine',.04)}}
    else if(boss.state==='air'){boss.vy+=1100*dt;boss.x+=boss.vx*dt;boss.y+=boss.vy*dt;boss.face=player.x<boss.x?-1:1;if(boss.y>=floor){boss.y=floor;boss.vy=0;boss.state='recover';boss.timer=.75;shake=10;sound(70,.3,'sawtooth',.07);puff(boss.x,floor-5,'#c7a77b',20,180);waves.push({x:boss.x-22,vx:-330,life:2},{x:boss.x+22,vx:330,life:2})}}
    else if(boss.state==='bellWind'){boss.timer-=dt;if(boss.timer<=0){boss.state='recover';boss.timer=.62;const a=Math.atan2(player.y-30-(boss.y-50),player.x-boss.x),speed=330;projectiles.push({x:boss.x+boss.face*35,y:boss.y-53,vx:Math.cos(a)*speed,vy:Math.sin(a)*speed-40,life:3});sound(245,.25,'sine',.05);puff(boss.x,boss.y-45,'#e1c98d',10,65)}}
    else if(boss.state==='recover'){boss.timer-=dt;boss.x+=boss.vx*dt;boss.vx*=.86;if(boss.timer<=0){boss.state='idle';boss.timer=boss.phase===2?.35:.8;boss.attackCd=boss.phase===2?.22:.35}}
    boss.x=clamp(boss.x,70,890);if(boss.state!=='air')boss.y=floor;
  }

